const learners = 600;
const searchesEach = 5;
const dailySearches = learners * searchesEach;
const openSeconds = 6 * 60 * 60;
const averageRate = dailySearches / openSeconds;
const busySearches = 1200;
const busySeconds = 10 * 60;
console.log("daily searches: " + dailySearches);
console.log("average per second: " + averageRate.toFixed(2));
console.log("busy per second: " + busySearches / busySeconds);
